import jdk.jfr.consumer.*;
import java.nio.file.*;
import java.util.*;

// Callees <file.jfr> <substring>: for samples whose stack holds a frame matching the substring,
// the frame just above it (its callee on the path to the top) and the top frame, counted.
public class Callees {
    public static void main(String[] a) throws Exception {
        Map<String,Integer> callee = new TreeMap<>(), top = new TreeMap<>();
        try (RecordingFile rf = new RecordingFile(Paths.get(a[0]))) {
            while (rf.hasMoreEvents()) {
                RecordedEvent e = rf.readEvent();
                if (!e.getEventType().getName().equals("jdk.ExecutionSample")) continue;
                RecordedStackTrace st = e.getStackTrace();
                if (st == null) continue;
                List<RecordedFrame> fs = st.getFrames();
                for (int i = fs.size() - 1; i >= 0; i--) {
                    RecordedMethod m = fs.get(i).getMethod();
                    if ((m.getType().getName() + "." + m.getName()).contains(a[1])) {
                        String c = i > 0 ? fs.get(i-1).getMethod().getType().getName() + "." + fs.get(i-1).getMethod().getName() + ":" + fs.get(i-1).getLineNumber() : "(self)";
                        callee.merge(c, 1, Integer::sum);
                        RecordedMethod t = fs.get(0).getMethod();
                        top.merge(t.getType().getName() + "." + t.getName(), 1, Integer::sum);
                        break;
                    }
                }
            }
        }
        System.out.println("== callees"); callee.entrySet().stream().sorted((x,y)->y.getValue()-x.getValue()).limit(12).forEach(x -> System.out.println(x.getValue() + "\t" + x.getKey()));
        System.out.println("== top frames"); top.entrySet().stream().sorted((x,y)->y.getValue()-x.getValue()).limit(12).forEach(x -> System.out.println(x.getValue() + "\t" + x.getKey()));
    }
}
